reversal.fixed_text:
loop {
    let ri = r.next().map(|x| x.to_ascii_lowercase());
    if ri.is_none() {
        return (true, l);
    } else if l.next().map(|x| x.to_ascii_lowercase()) != ri {
        return (false, l);
    }
}

reversal.parent_text:
loop {
    let li = l.next().map(|x| x.to_ascii_lowercase());
    let ri = r.next().map(|x| x.to_ascii_lowercase());
    if ri.is_none() {
        return (true, l);
    } else if li != ri {
        return (false, l);
    }
}
